package ma.lias.controller;
import ma.lias.entity.RoleHistory; import ma.lias.repository.RoleHistoryRepository; import ma.lias.service.AuditService; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@RestController @RequestMapping("/api/admin/roles-history") @PreAuthorize("hasRole('ADMIN')")
public class RoleHistoryController { private final RoleHistoryRepository repo; private final AuditService audit; public RoleHistoryController(RoleHistoryRepository repo, AuditService audit){this.repo=repo;this.audit=audit;} @GetMapping public List<RoleHistory> all(){return repo.findAll();} @PostMapping public ResponseEntity<RoleHistory> create(@RequestBody RoleHistory body){RoleHistory saved=repo.save(body); audit.log("CREATE","RoleHistory",saved.getId(),"Création"); return ResponseEntity.status(HttpStatus.CREATED).body(saved);} @PutMapping("/{id}") public RoleHistory update(@PathVariable Long id,@RequestBody RoleHistory body){if(!repo.existsById(id)) throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Introuvable"); body.setId(id); audit.log("UPDATE","RoleHistory",id,"Modification"); return repo.save(body);} }
